package io.github.jesterportfolio.hearth.survival.enchants;
import java.util.*;
/** ID와 저장 버전은 표시 이름·최대 레벨·enable 변경과 무관하다. */
public record EnchantDefinition(String id,String name,boolean enabled,int maxLevel,Set<String> equipment,Set<String> slots,Set<String> conflicts,Set<String> worlds,List<Rule> rules,Map<String,Object> document) {
    public enum Trigger { EQUIP,TICK,ATTACK,DEFEND,SHOOT,ARROW_HIT,ARROW_IMPACT,BREAK,DROP,INTERACT,KILL,DEATH,ALLY_DEATH,BLOCK_XP,MOB_XP }
    public enum Target { SELF,OTHER,ENEMIES,ALLIES,BLOCK }
    public record Effect(String type,Target target,Map<String,String> arguments,Map<String,Formula> expressions){public Effect(String type,Target target,Map<String,String> arguments){this(type,target,arguments,compile(arguments));}public Effect{expressions=Map.copyOf(expressions);arguments=Map.copyOf(arguments);if(!type.matches("[a-z][a-z0-9_]{0,40}"))throw new IllegalArgumentException("ENCHANT_EFFECT");}}
    private static Map<String,Formula> compile(Map<String,String> args){var out=new HashMap<String,Formula>();args.forEach((key,value)->{if(Set.of("amount","duration","radius","bonus","vertical","increment","maximum","expiry","lifetime").contains(key))out.put(key,Formula.of(value));});return out;}
    public record Rule(Trigger trigger,Formula condition,Formula chance,Formula cooldown,Formula duration,List<Effect> effects){public Rule{effects=List.copyOf(effects);if(effects.isEmpty()||effects.size()>32)throw new IllegalArgumentException("ENCHANT_EFFECTS");}}
    public EnchantDefinition {if(!id.matches("hearth:[a-z][a-z0-9_]{0,48}")||name.isBlank()||name.length()>80||maxLevel<1||maxLevel>1000||rules.isEmpty()||rules.size()>32)throw new IllegalArgumentException("ENCHANT_DEFINITION");equipment=Set.copyOf(equipment);slots=Set.copyOf(slots);conflicts=Set.copyOf(conflicts);worlds=Set.copyOf(worlds);rules=List.copyOf(rules);document=Collections.unmodifiableMap(new LinkedHashMap<>(document));}
    @SuppressWarnings("unchecked") public static EnchantDefinition parse(Map<String,Object> p){if(((Number)p.getOrDefault("version",0)).intValue()!=1)throw new IllegalArgumentException("ENCHANT_VERSION");var rules=new ArrayList<Rule>();for(var raw:(List<Map<String,Object>>)p.getOrDefault("rules",List.of())){var effects=new ArrayList<Effect>();for(var effect:(List<Map<String,Object>>)raw.getOrDefault("effects",List.of())){var args=new HashMap<String,String>();effect.forEach((k,v)->{if(!Set.of("type","target").contains(k))args.put(k,v.toString());});effects.add(new Effect(effect.get("type").toString(),Target.valueOf(effect.getOrDefault("target","SELF").toString()),args));}rules.add(new Rule(Trigger.valueOf(raw.get("trigger").toString()),f(raw,"condition","1"),f(raw,"chance","1"),f(raw,"cooldown","0"),f(raw,"duration","100"),effects));}if(!(p.get("enabled") instanceof Boolean enabled))throw new IllegalArgumentException("ENCHANT_ENABLED");return new EnchantDefinition(p.get("id").toString(),p.get("name").toString(),enabled,((Number)p.get("max-level")).intValue(),strings(p,"equipment"),strings(p,"slots"),strings(p,"conflicts"),strings(p,"worlds"),rules,p);}
    private static Formula f(Map<String,Object> p,String k,String d){return Formula.of(p.getOrDefault(k,d).toString());}
    private static Set<String> strings(Map<String,Object> p,String k){Object v=p.getOrDefault(k,List.of());if(!(v instanceof List<?> list))throw new IllegalArgumentException(k);return Set.copyOf(list.stream().map(Object::toString).toList());}
}
